<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {request,demoMode} from '@/services/quality'
import AppModal from '@/components/AppModal.vue'
const offices=ref<{id:number;name:string;status:string;profile_version:number}[]>([]);const selected=ref<typeof offices.value[number]|null>(null);const next=ref('suspended');const reason=ref('');const error=ref('');const busy=ref(false);const open=ref(false)
async function load(){try{offices.value=(await request<{data:typeof offices.value}>('/platform/officines')).data}catch(e){error.value=(e as Error).message}}
function edit(o:typeof offices.value[number]){selected.value=o;next.value=o.status==='archived'?'suspended':o.status==='suspended'?'active':'suspended';reason.value='';error.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{await request('/platform/officines/'+selected.value!.id+'/state','POST',{status:next.value,version:selected.value!.profile_version,reason:reason.value});open.value=false;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">ADMINISTRATION SAAS</p><h1>États des officines</h1><p class="page-subtitle">Suspension, réactivation et archivage sans suppression des données.</p></div></div><p v-if="demoMode" class="panel form-body">Disponible dans l’aperçu API.</p><template v-else><p v-if="error&&!open" class="alert error" role="alert">{{error}}</p><div class="panel"><div class="table-scroll"><table><thead><tr><th>OFFICINE</th><th>ÉTAT SAAS</th><th>VERSION</th><th>ACTION</th></tr></thead><tbody><tr v-for="o in offices" :key="o.id"><td>{{o.name}}</td><td>{{o.status}}</td><td>{{o.profile_version}}</td><td><button class="button secondary small" @click="edit(o)">Modifier l’état</button></td></tr></tbody></table></div></div></template><AppModal v-model="open" title="Modifier l’état de l’officine" :busy="busy"><form id="office-state" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>{{selected?.name}}</p><label>Nouvel état<select v-model="next"><option v-if="selected?.status!=='active'&&selected?.status!=='archived'" value="active">Réactiver</option><option v-if="selected?.status!=='suspended'" value="suspended">Suspendre / restaurer en suspension</option><option v-if="selected?.status!=='archived'" value="archived">Archiver</option></select></label><label>Motif obligatoire<textarea v-model="reason" rows="4" required maxlength="2000"/></label><p class="module-disclaimer">Suspendre ou archiver coupe les accès métier dès la requête suivante. Restaurer une archive la laisse suspendue jusqu’à une décision explicite de réactivation.</p></form><template #footer><button :disabled="busy" class="button secondary" @click="open=false">Annuler</button><button :disabled="busy" class="button primary" type="submit" form="office-state">Confirmer</button></template></AppModal></section></template>
